/**
 * questionConfig tests — pins the canonical `config` (opaque
 * google.protobuf.Struct) key names shared by every producer/consumer of a
 * question's config (manual editor forms, the AI-generation stub worker
 * `services/ask-svc/src/ask_svc/workers/generation/stub_generator.py`, and
 * its Python mirror `question_config.py`), plus the total, never-throw
 * reader helpers built on top of them.
 *
 * The readers must be total functions: a config is an opaque proto Struct
 * that can carry ANY JSON value under a given key (wrong producer, stale
 * shape, a key that's simply absent). None of these may throw — a single
 * malformed config must never crash a question card or the whole editor.
 */

import { describe, expect, it } from "vitest";
import {
  QUESTION_CONFIG_KEYS,
  readBoolean,
  readNumber,
  readString,
  readStringArray,
} from "../questionConfig";

describe("QUESTION_CONFIG_KEYS", () => {
  it("maps every canonical field to its snake_case wire key", () => {
    expect(QUESTION_CONFIG_KEYS).toEqual({
      helpText: "help_text",
      isDemographic: "is_demographic",
      options: "options",
      scaleMin: "scale_min",
      scaleMax: "scale_max",
      scaleMinLabel: "scale_min_label",
      scaleMaxLabel: "scale_max_label",
      matrixRows: "matrix_rows",
      matrixColumns: "matrix_columns",
      matrixAllowMultiple: "matrix_allow_multiple",
      minLength: "min_length",
      maxLength: "max_length",
      placeholder: "placeholder",
      allowDecimals: "allow_decimals",
      numberMin: "number_min",
      numberMax: "number_max",
      dateMin: "date_min",
      dateMax: "date_max",
      dateFormat: "date_format",
    });
  });
});

describe("readString", () => {
  it("returns the string when the key holds a string", () => {
    expect(readString({ [QUESTION_CONFIG_KEYS.helpText]: "Pick one" }, QUESTION_CONFIG_KEYS.helpText)).toBe(
      "Pick one",
    );
  });

  it("returns undefined when the key is missing", () => {
    expect(readString({}, QUESTION_CONFIG_KEYS.helpText)).toBeUndefined();
  });

  it("returns undefined when the value is the wrong type", () => {
    expect(readString({ [QUESTION_CONFIG_KEYS.helpText]: 42 }, QUESTION_CONFIG_KEYS.helpText)).toBeUndefined();
    expect(
      readString({ [QUESTION_CONFIG_KEYS.helpText]: true }, QUESTION_CONFIG_KEYS.helpText),
    ).toBeUndefined();
    expect(
      readString({ [QUESTION_CONFIG_KEYS.helpText]: ["a"] }, QUESTION_CONFIG_KEYS.helpText),
    ).toBeUndefined();
    expect(
      readString({ [QUESTION_CONFIG_KEYS.helpText]: { nested: true } }, QUESTION_CONFIG_KEYS.helpText),
    ).toBeUndefined();
  });

  it("returns undefined when the value is null", () => {
    expect(readString({ [QUESTION_CONFIG_KEYS.helpText]: null }, QUESTION_CONFIG_KEYS.helpText)).toBeUndefined();
  });
});

describe("readNumber", () => {
  it("returns the number when the key holds a finite number", () => {
    expect(readNumber({ [QUESTION_CONFIG_KEYS.scaleMin]: 1 }, QUESTION_CONFIG_KEYS.scaleMin)).toBe(1);
    expect(readNumber({ [QUESTION_CONFIG_KEYS.scaleMin]: 0 }, QUESTION_CONFIG_KEYS.scaleMin)).toBe(0);
    expect(readNumber({ [QUESTION_CONFIG_KEYS.scaleMin]: -3.5 }, QUESTION_CONFIG_KEYS.scaleMin)).toBe(-3.5);
  });

  it("returns undefined when the key is missing", () => {
    expect(readNumber({}, QUESTION_CONFIG_KEYS.scaleMax)).toBeUndefined();
  });

  it("returns undefined for NaN", () => {
    expect(readNumber({ [QUESTION_CONFIG_KEYS.scaleMax]: NaN }, QUESTION_CONFIG_KEYS.scaleMax)).toBeUndefined();
  });

  it("returns undefined for Infinity and -Infinity", () => {
    expect(
      readNumber({ [QUESTION_CONFIG_KEYS.scaleMax]: Infinity }, QUESTION_CONFIG_KEYS.scaleMax),
    ).toBeUndefined();
    expect(
      readNumber({ [QUESTION_CONFIG_KEYS.scaleMax]: -Infinity }, QUESTION_CONFIG_KEYS.scaleMax),
    ).toBeUndefined();
  });

  it("returns undefined when the value is a string, boolean, or null", () => {
    expect(readNumber({ [QUESTION_CONFIG_KEYS.scaleMax]: "5" }, QUESTION_CONFIG_KEYS.scaleMax)).toBeUndefined();
    expect(
      readNumber({ [QUESTION_CONFIG_KEYS.scaleMax]: false }, QUESTION_CONFIG_KEYS.scaleMax),
    ).toBeUndefined();
    expect(
      readNumber({ [QUESTION_CONFIG_KEYS.scaleMax]: null }, QUESTION_CONFIG_KEYS.scaleMax),
    ).toBeUndefined();
  });
});

describe("readBoolean", () => {
  it("returns the boolean when the key holds a boolean", () => {
    expect(
      readBoolean({ [QUESTION_CONFIG_KEYS.isDemographic]: true }, QUESTION_CONFIG_KEYS.isDemographic),
    ).toBe(true);
    expect(
      readBoolean({ [QUESTION_CONFIG_KEYS.isDemographic]: false }, QUESTION_CONFIG_KEYS.isDemographic),
    ).toBe(false);
  });

  it("returns undefined when the key is missing", () => {
    expect(readBoolean({}, QUESTION_CONFIG_KEYS.isDemographic)).toBeUndefined();
  });

  it("returns undefined for a non-boolean value", () => {
    expect(
      readBoolean({ [QUESTION_CONFIG_KEYS.isDemographic]: "true" }, QUESTION_CONFIG_KEYS.isDemographic),
    ).toBeUndefined();
    expect(
      readBoolean({ [QUESTION_CONFIG_KEYS.isDemographic]: 1 }, QUESTION_CONFIG_KEYS.isDemographic),
    ).toBeUndefined();
    expect(
      readBoolean({ [QUESTION_CONFIG_KEYS.isDemographic]: null }, QUESTION_CONFIG_KEYS.isDemographic),
    ).toBeUndefined();
  });
});

describe("readStringArray", () => {
  it("returns the array as-is when every entry is a string", () => {
    expect(
      readStringArray({ [QUESTION_CONFIG_KEYS.options]: ["Low", "High"] }, QUESTION_CONFIG_KEYS.options),
    ).toEqual(["Low", "High"]);
  });

  it("filters out non-string entries, mirroring summarizeQuestionConfig's rationale", () => {
    expect(
      readStringArray(
        { [QUESTION_CONFIG_KEYS.options]: ["Low", { bad: 1 }, "High", 42, null] },
        QUESTION_CONFIG_KEYS.options,
      ),
    ).toEqual(["Low", "High"]);
  });

  it("returns undefined — never an empty array — when every entry is filtered out", () => {
    // Every entry here is genuinely non-string (a number and an object) so
    // the filtered result is empty; a string that merely LOOKS like a
    // number description (e.g. "42") would survive the typeof === "string"
    // filter per the documented contract and must NOT be used here.
    expect(
      readStringArray(
        { [QUESTION_CONFIG_KEYS.options]: [42, { not: "a string" }] },
        QUESTION_CONFIG_KEYS.options,
      ),
    ).toBeUndefined();
  });

  it("returns undefined for an empty array", () => {
    expect(readStringArray({ [QUESTION_CONFIG_KEYS.options]: [] }, QUESTION_CONFIG_KEYS.options)).toBeUndefined();
  });

  it("returns undefined when the value is not an array", () => {
    expect(
      readStringArray({ [QUESTION_CONFIG_KEYS.options]: "not an array" }, QUESTION_CONFIG_KEYS.options),
    ).toBeUndefined();
    expect(readStringArray({ [QUESTION_CONFIG_KEYS.options]: 42 }, QUESTION_CONFIG_KEYS.options)).toBeUndefined();
    expect(
      readStringArray({ [QUESTION_CONFIG_KEYS.options]: null }, QUESTION_CONFIG_KEYS.options),
    ).toBeUndefined();
    expect(readStringArray({}, QUESTION_CONFIG_KEYS.options)).toBeUndefined();
  });
});


