/**
 * listSurveys query-param + status_counts tests (fix/ask-survey-list-ui) —
 * the ask-bff now does filter/sort/search/counts server-side; listSurveys
 * builds the query string and parses the org-wide `status_counts` block.
 */
describe("listSurveys query params", () => {
  it("fetches the bare path when called with no params", async () => {
    const spy = vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({
        data: { surveys: [], next_page_token: "", status_counts: { total: 0, draft: 0, published: 0, closed: 0 } },
      }),
    );

    await listSurveys();

    expect(spy).toHaveBeenCalledWith(
      "/api/v1/ask/surveys",
      expect.objectContaining({ credentials: "include" }),
    );
  });

  it("builds the query string from status/search/sort/order params", async () => {
    const spy = vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({
        data: { surveys: [], next_page_token: "", status_counts: { total: 0, draft: 0, published: 0, closed: 0 } },
      }),
    );

    await listSurveys({
      status: "draft",
      search: "pulse",
      sort: "created_at",
      order: "desc",
    });

    const [url] = spy.mock.calls[0] as [string, RequestInit];
    const parsed = new URL(url, "http://localhost");
    expect(parsed.pathname).toBe("/api/v1/ask/surveys");
    expect(parsed.searchParams.get("status")).toBe("draft");
    expect(parsed.searchParams.get("q")).toBe("pulse");
    expect(parsed.searchParams.get("sort")).toBe("created_at");
    expect(parsed.searchParams.get("order")).toBe("desc");
  });

  it("omits a param from the query string when absent", async () => {
    const spy = vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({
        data: { surveys: [], next_page_token: "", status_counts: { total: 0, draft: 0, published: 0, closed: 0 } },
      }),
    );

    await listSurveys({ sort: "title", order: "asc" });

    const [url] = spy.mock.calls[0] as [string, RequestInit];
    const parsed = new URL(url, "http://localhost");
    expect(parsed.searchParams.has("status")).toBe(false);
    expect(parsed.searchParams.has("q")).toBe(false);
    expect(parsed.searchParams.get("sort")).toBe("title");
    expect(parsed.searchParams.get("order")).toBe("asc");
  });

  it("omits an empty search string from the query string", async () => {
    const spy = vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({
        data: { surveys: [], next_page_token: "", status_counts: { total: 0, draft: 0, published: 0, closed: 0 } },
      }),
    );

    await listSurveys({ search: "" });

    const [url] = spy.mock.calls[0] as [string, RequestInit];
    const parsed = new URL(url, "http://localhost");
    expect(parsed.searchParams.has("q")).toBe(false);
  });

  it("parses status_counts from the response envelope", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({
        data: {
          surveys: [],
          next_page_token: "",
          status_counts: { total: 9, draft: 3, published: 4, closed: 2 },
        },
      }),
    );

    const result = await listSurveys();

    expect(result.status_counts).toEqual({
      total: 9,
      draft: 3,
      published: 4,
      closed: 2,
    });
  });

  it("defaults status_counts to zeros when the field is absent", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: { surveys: [], next_page_token: "" } }),
    );

    const result = await listSurveys();

    expect(result.status_counts).toEqual({
      total: 0,
      draft: 0,
      published: 0,
      closed: 0,
    });
  });

  it("defaults status_counts to zeros when the field is malformed", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({
        data: { surveys: [], next_page_token: "", status_counts: { total: "nine" } },
      }),
    );

    const result = await listSurveys();

    expect(result.status_counts).toEqual({
      total: 0,
      draft: 0,
      published: 0,
      closed: 0,
    });
  });
});

