/**
 * branches API tests (story #1995) — the two colon-actions ask-bff exposes
 * for answer branching, plus the normalizer that keeps `QuestionDTO.branches`
 * an array no matter what the wire sends.
 *
 * Direct fetch-spy style, mirroring questions.test.ts.
 */

import { afterEach, describe, expect, it, vi } from "vitest";

import {
  normalizeBranch,
  normalizeBranches,
  removeBranch,
  setBranch,
} from "../branches";
import { AskApiError } from "../surveys";

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

afterEach(() => {
  vi.restoreAllMocks();
});

const WIRE_BRANCH = {
  id: "br-1",
  questionId: "q1",
  optionValue: "Very favorable",
  target: { kind: "question", id: "q3" },
};

describe("setBranch", () => {
  it("POSTs to the branches:set colon-action with the option in the BODY", async () => {
    const spy = vi
      .spyOn(globalThis, "fetch")
      .mockResolvedValue(jsonResponse({ data: WIRE_BRANCH }));

    await setBranch("s1", "q1", "Very favorable", { kind: "question", id: "q3" });

    const [url, init] = spy.mock.calls[0] ?? [];
    // The option travels in the body, never the path: it is arbitrary user
    // text that can contain slashes.
    expect(url).toBe("/api/v1/ask/surveys/s1/questions/q1/branches:set");
    expect(init?.method).toBe("POST");
    expect(init?.credentials).toBe("include");
    expect(JSON.parse(String(init?.body))).toEqual({
      optionValue: "Very favorable",
      target: { kind: "question", id: "q3" },
    });
  });

  it("returns the normalized branch from the data envelope", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(jsonResponse({ data: WIRE_BRANCH }));

    const result = await setBranch("s1", "q1", "Very favorable", {
      kind: "question",
      id: "q3",
    });

    expect(result).toEqual({
      id: "br-1",
      questionId: "q1",
      optionValue: "Very favorable",
      target: { kind: "question", id: "q3" },
    });
  });

  it("sends an end target with an empty id", async () => {
    const spy = vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: { ...WIRE_BRANCH, target: { kind: "end", id: "" } } }),
    );

    await setBranch("s1", "q1", "A", { kind: "end", id: "" });

    const body = JSON.parse(String(spy.mock.calls[0]?.[1]?.body));
    expect(body.target).toEqual({ kind: "end", id: "" });
  });

  it("throws an AskApiError on a non-2xx response", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ error: { message: "a branch can only target a later question" } }, 400),
    );

    await expect(
      setBranch("s1", "q1", "A", { kind: "question", id: "q0" }),
    ).rejects.toBeInstanceOf(AskApiError);
  });
});

describe("removeBranch", () => {
  it("POSTs to the branches:remove colon-action with the option in the body", async () => {
    const spy = vi
      .spyOn(globalThis, "fetch")
      .mockResolvedValue(jsonResponse({ data: WIRE_BRANCH }));

    await removeBranch("s1", "q1", "Very favorable");

    const [url, init] = spy.mock.calls[0] ?? [];
    expect(url).toBe("/api/v1/ask/surveys/s1/questions/q1/branches:remove");
    expect(init?.method).toBe("POST");
    expect(JSON.parse(String(init?.body))).toEqual({ optionValue: "Very favorable" });
  });

  it("returns the branch as it was before removal", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(jsonResponse({ data: WIRE_BRANCH }));

    const result = await removeBranch("s1", "q1", "Very favorable");

    expect(result.target.id).toBe("q3");
  });

  it("throws an AskApiError when the branch is unknown", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ error: { message: "branch not found" } }, 404),
    );

    await expect(removeBranch("s1", "q1", "never branched")).rejects.toBeInstanceOf(
      AskApiError,
    );
  });
});

describe("normalizeBranch", () => {
  it("maps a well-formed row straight across", () => {
    expect(normalizeBranch(WIRE_BRANCH)).toEqual({
      id: "br-1",
      questionId: "q1",
      optionValue: "Very favorable",
      target: { kind: "question", id: "q3" },
    });
  });

  it("degrades an unrecognized kind to end rather than inventing a target", () => {
    // "end" is the one target that is always valid regardless of what else is
    // in the survey, so a corrupt row renders as a harmless route-to-finish
    // instead of a dangling pointer at something that may not exist.
    const result = normalizeBranch({ ...WIRE_BRANCH, target: { kind: "sideways", id: "x" } });

    expect(result.target).toEqual({ kind: "end", id: "" });
  });

  it("forces an end branch's id empty even when the server sent one", () => {
    // `kind` is authoritative; the two must never disagree.
    const result = normalizeBranch({ ...WIRE_BRANCH, target: { kind: "end", id: "q9" } });

    expect(result.target.id).toBe("");
  });

  it("degrades every missing field rather than throwing", () => {
    expect(normalizeBranch(undefined)).toEqual({
      id: "",
      questionId: "",
      optionValue: "",
      target: { kind: "end", id: "" },
    });
  });

  it("drops a non-string id to the empty string", () => {
    const result = normalizeBranch({ ...WIRE_BRANCH, target: { kind: "question", id: 7 } });

    expect(result.target.id).toBe("");
  });
});

describe("normalizeBranches", () => {
  it("maps every row", () => {
    expect(normalizeBranches([WIRE_BRANCH, WIRE_BRANCH])).toHaveLength(2);
  });

  it("degrades an absent value to [] — the always-an-array promise", () => {
    expect(normalizeBranches(undefined)).toEqual([]);
  });

  it("degrades a non-array value to []", () => {
    expect(normalizeBranches({ nope: true })).toEqual([]);
  });
});


