/**
 * questions API tests (#1278) — typed fetch wrapper for GET
 * /api/v1/ask/surveys/{id}/questions. Confirmed live against
 * services/ask-bff/internal/handlers/question.go's ListQuestions handler:
 * `{ data: { questions: [...], next_page_token } }` envelope, camelCase
 * `questionType`/`sectionId` fields, no `survey_id` field on a question row
 * (the survey id is already known from the route param, so the BFF never
 * repeats it per-row). Mirrors surveys.test.ts's direct fetch-spy style.
 */

import { afterEach, describe, expect, it, vi } from "vitest";
import {
  createQuestion,
  deleteQuestion,
  getQuestion,
  listQuestions,
  reorderQuestions,
  updateQuestion,
} from "../questions";
import { AskApiError } from "../surveys";

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

afterEach(() => {
  vi.restoreAllMocks();
});

describe("listQuestions", () => {
  it("fetches /api/v1/ask/surveys/{id}/questions with credentials included", async () => {
    const spy = vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: { questions: [], next_page_token: "" } }),
    );

    await listQuestions("survey-1");

    expect(spy).toHaveBeenCalledWith(
      "/api/v1/ask/surveys/survey-1/questions",
      expect.objectContaining({ credentials: "include" }),
    );
  });

  it("forwards page_size and page_token as query params when provided", async () => {
    const spy = vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: { questions: [], next_page_token: "" } }),
    );

    await listQuestions("survey-1", { pageSize: 50, pageToken: "tok-1" });

    expect(spy).toHaveBeenCalledWith(
      "/api/v1/ask/surveys/survey-1/questions?page_size=50&page_token=tok-1",
      expect.objectContaining({ credentials: "include" }),
    );
  });

  it("returns the questions array and next_page_token from the data envelope", async () => {
    const question = {
      id: "q-1",
      questionType: "single_select",
      prompt: "How satisfied are you?",
      position: 0,
      required: true,
      config: { options: ["Low", "Medium", "High"] },
      sectionId: "sec-1",
    };
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: { questions: [question], next_page_token: "tok-2" } }),
    );

    const result = await listQuestions("survey-1");

    // `branches: []` is supplied by `normalizeQuestion` for a wire row that
    // omits the field — the always-an-array promise, asserted here rather
    // than papered over by adding the key to the fixture.
    expect(result.questions).toEqual([{ ...question, branches: [] }]);
    expect(result.next_page_token).toBe("tok-2");
  });

  // ask-bff dropped `omitempty` on this field, so an implicit-run question now
  // arrives as `"sectionId": ""` rather than with the key absent — the key has
  // to be PRESENT for a GET → mutate → PATCH round trip to be able to send the
  // same `""` back as the "move to the implicit run" clear sentinel. `""` is not
  // a section id, so it must normalise to ABSENT here; left as a literal empty
  // string, every implicit question would arrive carrying a `sectionId` that is
  // present-but-meaningless, and anything testing `=== undefined` alone would
  // read it as sectioned.
  it("normalizes an empty-string sectionId to undefined — ask-bff's non-omitempty implicit-run shape", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({
        data: {
          questions: [
            {
              id: "q-1",
              questionType: "free_text",
              prompt: "Anything else?",
              position: 0,
              required: false,
              config: {},
              sectionId: "",
            },
          ],
          next_page_token: "",
        },
      }),
    );

    const result = await listQuestions("survey-1");

    expect(result.questions[0]?.sectionId).toBeUndefined();
    // Specifically NOT the empty string — the whole point of the guard.
    expect(result.questions[0]).not.toHaveProperty("sectionId", "");
  });

  it("normalizes a null questions field to an empty array", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: { questions: null, next_page_token: null } }),
    );

    const result = await listQuestions("survey-1");

    expect(result.questions).toEqual([]);
    expect(result.next_page_token).toBe("");
  });

  it("normalizes an absent questions field to an empty array", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(jsonResponse({ data: {} }));

    const result = await listQuestions("survey-1");

    expect(result.questions).toEqual([]);
    expect(result.next_page_token).toBe("");
  });

  it("defaults a question's missing config to an empty object", async () => {
    const question = {
      id: "q-1",
      questionType: "free_text",
      prompt: "Anything else?",
      position: 1,
      required: false,
    };
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: { questions: [question] } }),
    );

    const result = await listQuestions("survey-1");

    expect(result.questions[0]?.config).toEqual({});
  });

  it("throws an AskApiError carrying the status and parsed error message on a non-ok response", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse(
        { data: null, error: { code: "not_found", message: "survey not found" } },
        404,
      ),
    );

    await expect(listQuestions("missing")).rejects.toMatchObject({
      name: "AskApiError",
      status: 404,
      message: "survey not found",
    });
  });

  it("is a real AskApiError instance", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: null, error: { code: "forbidden", message: "nope" } }, 403),
    );

    await expect(listQuestions("survey-1")).rejects.toBeInstanceOf(AskApiError);
  });
});

describe("createQuestion", () => {
  const request = {
    questionType: "single_select" as const,
    prompt: "How satisfied are you?",
    required: true,
    config: { options: ["Low", "High"] },
    sectionId: "sec-1",
  };

  it("POSTs to /api/v1/ask/surveys/{id}/questions with credentials, headers, and body", async () => {
    const question = {
