    );

    await createQuestion("survey-1", request);

    expect(spy).toHaveBeenCalledWith("/api/v1/ask/surveys/survey-1/questions", {
      method: "POST",
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(request),
    });
  });

  it("returns the created QuestionDTO on 201", async () => {
    const question = {
      id: "q-1",
      questionType: "single_select",
      prompt: "How satisfied are you?",
      position: 0,
