/**
 * sections API tests (#1283) — typed fetch wrapper for the ask-bff Section
 * CRUD routes (docs/design/ask-sections.md §4.1, plan step C2):
 * GET/POST /api/v1/ask/surveys/{id}/sections and
 * PATCH/DELETE /api/v1/ask/surveys/{id}/sections/{sectionId}.
 *
 * Mirrors questions.test.ts's/surveys.test.ts's direct fetch-spy style for
 * api-layer unit tests, per those files' own doc comments: MSW is reserved
 * for component/hook-level tests that exercise the network through React,
 * not for these fetch-wrapper unit tests. `tests/msw/handlers.ts` has no
 * section routes yet (that's plan step C15, a separate lane) so this file
 * does not touch it.
 *
 * `SectionSummary` only needs `id`/`title`/`description`/`position` per the
 * design doc — the wire DTO also carries `surveyId`/`createdAt`/`updatedAt`,
 * which normalizeSection is free to ignore.
 */

import { afterEach, describe, expect, it, vi } from "vitest";
import {
  createSection,
  deleteSection,
  listSections,
  reorderSections,
  updateSection,
} from "../sections";
import { AskApiError } from "../surveys";

function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "Content-Type": "application/json" },
  });
}

afterEach(() => {
  vi.restoreAllMocks();
});

describe("listSections", () => {
  it("fetches /api/v1/ask/surveys/{id}/sections with credentials included", async () => {
    const spy = vi
      .spyOn(globalThis, "fetch")
      .mockResolvedValue(jsonResponse({ data: { sections: [] } }));

    await listSections("survey-1");

    expect(spy).toHaveBeenCalledWith(
      "/api/v1/ask/surveys/survey-1/sections",
      expect.objectContaining({ credentials: "include" }),
    );
  });

  it("returns the sections array unwrapped from the data envelope, keeping only the SectionSummary fields", async () => {
    const section = {
      id: "sec-1",
      surveyId: "survey-1",
      title: "Brand perception",
      description: "Shown to everyone",
      position: 0,
      createdAt: "2026-07-31T00:00:00Z",
      updatedAt: "2026-07-31T00:00:00Z",
    };
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: { sections: [section] } }),
    );

    const result = await listSections("survey-1");

    expect(result).toEqual([
      {
        id: "sec-1",
        title: "Brand perception",
        description: "Shown to everyone",
        position: 0,
      },
    ]);
  });

  it("normalizes a malformed row's title/description/position/id rather than dropping it", async () => {
    const goodSection = {
      id: "sec-1",
      surveyId: "survey-1",
      title: "Brand perception",
      description: "",
      position: 0,
    };
    const malformedSection = {
      // id missing entirely
      surveyId: "survey-1",
      title: 42, // wrong type
      description: null, // wrong type
      position: "not-a-number", // wrong type
    };
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: { sections: [goodSection, malformedSection] } }),
    );

    const result = await listSections("survey-1");

    // The malformed row is neither dropped nor does it throw — it appears,
    // normalized, alongside the good row.
    expect(result).toHaveLength(2);
    expect(result[0]).toEqual({
      id: "sec-1",
      title: "Brand perception",
      description: "",
      position: 0,
    });
    expect(result[1]).toEqual({
      id: "",
      title: "",
      description: "",
      position: 0,
    });
  });

  it("normalizes a null/absent sections field to an empty array", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ data: { sections: null } }),
    );

    await expect(listSections("survey-1")).resolves.toEqual([]);

    vi.spyOn(globalThis, "fetch").mockResolvedValue(jsonResponse({ data: {} }));

    await expect(listSections("survey-1")).resolves.toEqual([]);
  });

  it("throws an AskApiError carrying the status and parsed error message on a non-ok response", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse(
        { data: null, error: { code: "not_found", message: "survey not found" } },
        404,
      ),
    );

    await expect(listSections("missing")).rejects.toMatchObject({
      name: "AskApiError",
      status: 404,
      message: "survey not found",
    });
    await expect(listSections("missing")).rejects.toBeInstanceOf(AskApiError);
  });
});

