    const [url, init] = fetchSpy.mock.calls[0] ?? [];
    // No query string when no reason is given — an empty `?reason=` would be
    // a different request than "no reason".
    expect(url).toBe("/api/v1/ask/surveys/s1");
    expect((init as RequestInit).method).toBe("DELETE");
  });

  it("appends the reason as a query parameter when given", async () => {
    const fetchSpy = vi
      .spyOn(globalThis, "fetch")
      .mockResolvedValue(jsonResponse({ data: { id: "s1" } }));

    await deleteSurvey("s1", "obsolete & noisy");

    expect(fetchSpy.mock.calls[0]?.[0]).toBe(
      "/api/v1/ask/surveys/s1?reason=obsolete+%26+noisy",
    );
  });

  it("omits the query string for a blank reason", async () => {
    const fetchSpy = vi
      .spyOn(globalThis, "fetch")
      .mockResolvedValue(jsonResponse({ data: { id: "s1" } }));

    await deleteSurvey("s1", "   ");

    expect(fetchSpy.mock.calls[0]?.[0]).toBe("/api/v1/ask/surveys/s1");
  });

  it("throws AskApiError on a non-2xx", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({ error: "nope" }, 404),
    );
    await expect(deleteSurvey("s1")).rejects.toBeInstanceOf(AskApiError);
  });

  it("throws on a malformed 2xx rather than returning an undefined id", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(jsonResponse({ data: {} }));
    await expect(deleteSurvey("s1")).rejects.toBeInstanceOf(AskApiError);
  });
});

