describe("updateSurvey", () => {
  it("PATCHes /api/v1/ask/surveys/{id} with the patch body and credentials", async () => {
    const spy = vi
      .spyOn(globalThis, "fetch")
      .mockResolvedValue(jsonResponse({ data: { id: "s1", title: "T" } }));

    await updateSurvey("s1", { completion_message: "Thanks!" });

    expect(spy).toHaveBeenCalledWith("/api/v1/ask/surveys/s1", {
      method: "PATCH",
      credentials: "include",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ completion_message: "Thanks!" }),
    });
  });

  it("serializes an empty completion_message rather than dropping it", async () => {
    // The clear operation (story #1284 journey step 6). JSON.stringify keeps
    // "" for an explicitly-present key, and ask-bff's pointer field then
    // forwards it as PRESENT-and-empty. A patch builder that omitted the key
    // would instead mean "keep existing" and the old message would survive.
    const spy = vi
      .spyOn(globalThis, "fetch")
      .mockResolvedValue(jsonResponse({ data: { id: "s1" } }));

    await updateSurvey("s1", { completion_message: "" });

    const init = spy.mock.calls[0]?.[1];
    expect(init?.body).toBe('{"completion_message":""}');
  });

  it("preserves newlines in the completion message", async () => {
    const spy = vi
      .spyOn(globalThis, "fetch")
      .mockResolvedValue(jsonResponse({ data: { id: "s1" } }));

    await updateSurvey("s1", { completion_message: "Thanks!\n\nAll done." });

    const init = spy.mock.calls[0]?.[1];
    expect(JSON.parse(String(init?.body)) as unknown).toEqual({
      completion_message: "Thanks!\n\nAll done.",
    });
  });

  it("returns the updated survey", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse({
        data: { id: "s1", title: "Renamed", completion_message: "Thanks!" },
      }),
    );

    const survey = await updateSurvey("s1", { title: "Renamed" });

    expect(survey.id).toBe("s1");
    expect(survey.title).toBe("Renamed");
    expect(survey.completion_message).toBe("Thanks!");
  });

  it("throws AskApiError on a non-2xx response", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(
      jsonResponse(
        { error: { code: "validation_failed", message: "too long" } },
        400,
      ),
    );

    await expect(updateSurvey("s1", { completion_message: "x" })).rejects.toBeInstanceOf(
      AskApiError,
    );
  });

  it("throws on a malformed 2xx body rather than returning an id-less survey", async () => {
    vi.spyOn(globalThis, "fetch").mockResolvedValue(jsonResponse({ data: {} }));

    await expect(updateSurvey("s1", { title: "T" })).rejects.toBeInstanceOf(AskApiError);
  });
});

